import json
from hypothesis import strategies as st

MOD = 10**9 + 7


@st.composite
def gen(draw):
    n = draw(st.integers(2, 6))
    alphabet = draw(st.sampled_from(["ab", "abc", "a"]))
    s = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
    if draw(st.booleans()):
        # t is a rotation of s (sometimes trivial, sometimes periodic)
        r = draw(st.integers(0, n - 1))
        t = s[n - r:] + s[:n - r] if r else s
    else:
        t = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
    k = draw(st.integers(1, 6))
    return f"{json.dumps(s)}\n{json.dumps(t)}\n{json.dumps(k)}\n"


