        return False
    return True


def ref(inp):
    lines = [x for x in inp.split("\n") if x.strip()]
    s = json.loads(lines[0])
    t = json.loads(lines[1])
    k = json.loads(lines[2])
    n = len(s)
    # Literal simulation: count ways to reach each string after each operation.
    cur = {s: 1}
    for _ in range(k):
        nxt = {}
        for w, c in cur.items():
            for l in range(1, n):
                # remove suffix of length l, put it in front
                nw = w[n - l:] + w[:n - l]
                nxt[nw] = (nxt.get(nw, 0) + c) % MOD
        cur = nxt
    return str(cur.get(t, 0) % MOD)
